/**
 * Bulk archive for the issue list. Duplicate ids count once. Unknown, foreign
 * and already-archived ids are skipped and left untouched; every other issue
 * must pass the single-archive `issue:archive` check, and one failure rejects
 * the whole call before anything is written. Each archived issue publishes
 * `issue.archived`, exactly as a single archive does.
 */
export async function bulkArchiveIssues(
  actor: Actor,
  input: BulkArchiveIssuesInput,
): Promise<{ archived: readonly IssueId[]; skipped: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const requested = [...new Set(input.issueIds)];
  const found = await issueRepo.findIssuesByIds(input.orgId, requested);
  const byId = new Map(found.map((issue) => [issue.id, issue]));

  const skipped: IssueId[] = [];
  const targets: Issue[] = [];
  for (const issueId of requested) {
    const issue = byId.get(issueId);
    if (issue === undefined || isArchived(issue)) {
      skipped.push(issueId);
      continue;
    }
    assertCan(actor, "issue:archive", issueResource(issue));
    targets.push(issue);
  }

  const archived: IssueId[] = [];
  for (const issue of targets) {
    const row = await issueRepo.archiveIssue(input.orgId, issue.id);
    archived.push(row.id);

    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: row.id,
      projectId: row.projectId,
    });
  }

  return { archived, skipped };
}

